package store

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sync"
)

const runsDir = "./data/runs"

// Report represents the data to be stored for a run
// We keep it generic as map[string]interface{} to allow flexible report
// For simplicity, we store it as JSON to file runId.json

type Report map[string]interface{}

// RunStore provides methods to save and list run reports

type RunStore struct {
	mu sync.Mutex
}

func NewRunStore() *RunStore {
	return &RunStore{}
}

// Save persists the report to ./data/runs/<runId>.json atomically
func (s *RunStore) Save(runID string, report Report) error {
	if runID == "" {
		return errors.New("runID cannot be empty")
	}

	// Create directory if not exists
	if err := os.MkdirAll(runsDir, 0o755); err != nil {
		return fmt.Errorf("failed to create data dir: %w", err)
	}

	// Marshal report to JSON
	data, err := json.MarshalIndent(report, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal report json: %w", err)
	}

	// Write temp file first
	tempFile := filepath.Join(runsDir, runID+".json.tmp")
	finalFile := filepath.Join(runsDir, runID+".json")

	if err := os.WriteFile(tempFile, data, 0o644); err != nil {
		return fmt.Errorf("failed to write temp report file: %w", err)
	}

	// Rename temp to final atomically
	if err := os.Rename(tempFile, finalFile); err != nil {
		return fmt.Errorf("failed to rename report file: %w", err)
	}

	return nil
}

// List returns at most 'limit' runIDs ordered by filename ascending
func (s *RunStore) List(limit int) ([]string, error) {
	entries, err := os.ReadDir(runsDir)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return []string{}, nil
		}
		return nil, fmt.Errorf("failed to read runs dir: %w", err)
	}

	var runIDs []string
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		name := e.Name()
		if filepath.Ext(name) != ".json" {
			continue
		}
		runID := name[:len(name)-len(".json")]
		runIDs = append(runIDs, runID)
	}

	// Limit the results
	if limit > 0 && len(runIDs) > limit {
		runIDs = runIDs[:limit]
	}

	return runIDs, nil
}

// Extra: Load returns loaded report for a given runID (not in spec but can be useful)
func (s *RunStore) Load(runID string) (Report, error) {
	if runID == "" {
		return nil, errors.New("runID cannot be empty")
	}

	file := filepath.Join(runsDir, runID+".json")
	data, err := os.ReadFile(file)
	if err != nil {
		return nil, fmt.Errorf("failed to read report file: %w", err)
	}

	var report Report
	if err := json.Unmarshal(data, &report); err != nil {
		return nil, fmt.Errorf("failed to unmarshal report json: %w", err)
	}

	return report, nil
}

package store

import (
	"os"
	"path/filepath"
	"testing"
	"time"
)

func TestRunStore_SaveAndList(t *testing.T) {
	s := NewRunStore()

	runID := "test-run-123"
	report := Report{
		"runId": runID,
		"status": "completed",
		"requests": 10,
		"errors": 1,
	}

	// Clean up before test
	_ = os.Remove(filepath.Join(runsDir, runID+".json"))

	if err := s.Save(runID, report); err != nil {
		t.Fatalf("Save failed: %v", err)
	}

	// Check file exists
	file := filepath.Join(runsDir, runID+".json")
	fi, err := os.Stat(file)
	if err != nil {
		t.Fatalf("expected file to exist after save: %v", err)
	}
	if fi.Size() == 0 {
		t.Fatalf("saved file is empty")
	}

	// Test List
	runIDs, err := s.List(10)
	if err != nil {
		t.Fatalf("List failed: %v", err)
	}

	found := false
	for _, id := range runIDs {
		if id == runID {
			found = true
			break
		}
	}

	if !found {
		t.Errorf("List missing saved runID")
	}

	// Test List with limit
	moreIDs := []string{"a", "b", "c"}
	for _, id := range moreIDs {
		_ = s.Save(id, Report{"name": id})
	}

	runIDsLimited, err := s.List(2)
	if err != nil {
		t.Fatalf("List with limit failed: %v", err)
	}

	if len(runIDsLimited) != 2 {
		t.Errorf("expected 2 results, got %d", len(runIDsLimited))
	}

	// Cleanup
	_ = os.Remove(file)
	for _, id := range moreIDs {
		_ = os.Remove(filepath.Join(runsDir, id+".json"))
	}
}

func TestRunStore_Save_EmptyRunID(t *testing.T) {
	s := NewRunStore()
	err := s.Save("", Report{})
	if err == nil {
		t.Fatal("expected error for empty runID")
	}
}

func TestRunStore_List_NonExistentDir(t *testing.T) {
	s := NewRunStore()
	// Temporarily rename runsDir if exists
	runsDirTemp := runsDir + "_temp"
	_ = os.RemoveAll(runsDirTemp)
	_ = os.Rename(runsDir, runsDirTemp)
	defer func() {
		_ = os.Rename(runsDirTemp, runsDir)
	}()

	got, err := s.List(10)
	if err != nil {
		t.Fatalf("List error unexpected: %v", err)
	}
	if len(got) != 0 {
		t.Errorf("expected empty list for non-existent dir")
	}
}

func TestRunStore_Save_AtomicWrite(t *testing.T) {
	s := NewRunStore()

	runID := "atomic-run"
	report := Report{"val": "data"}

	// Clean up
	_ = os.Remove(filepath.Join(runsDir, runID+".json"))
	_ = os.Remove(filepath.Join(runsDir, runID+".json.tmp"))

	if err := s.Save(runID, report); err != nil {
		t.Fatalf("Save failed: %v", err)
	}

	// There should be no temp file left
	tmpPath := filepath.Join(runsDir, runID+".json.tmp")
	if _, err := os.Stat(tmpPath); err == nil {
		t.Errorf("temporary file should not exist after Save")
	}

	// cleanup
	_ = os.Remove(filepath.Join(runsDir, runID+".json"))
}

func TestRunStore_Load(t *testing.T) {
	s := NewRunStore()

	runID := "load-run-1"
	report := Report{"foo": "bar"}

	// Clean up
	_ = os.Remove(filepath.Join(runsDir, runID+".json"))

	if err := s.Save(runID, report); err != nil {
		t.Fatalf("Save failed: %v", err)
	}

	loaded, err := s.Load(runID)
	if err != nil {
		t.Fatalf("Load failed: %v", err)
	}

	if loaded["foo"] != "bar" {
		t.Errorf("expected foo=bar, got %v", loaded["foo"])
	}

	// Load non-existent
	_, err = s.Load("not-exist")
	if err == nil {
		t.Error("expected error for non-existent runID")
	}

	// cleanup
	_ = os.Remove(filepath.Join(runsDir, runID+".json"))
}

func TestRunStore_List_LimitZero(t *testing.T) {
	s := NewRunStore()

	// Save some runs
	runs := []string{"r1", "r2", "r3"}
	for _, runID := range runs {
		_ = s.Save(runID, Report{"val": runID})
	}

	list, err := s.List(0) // limit zero means no limit
	if err != nil {
		t.Fatalf("List error: %v", err)
	}

	if len(list) < len(runs) {
		t.Errorf("expected at least %d items, got %d", len(runs), len(list))
	}

	// Cleanup
	for _, runID := range runs {
		_ = os.Remove(filepath.Join(runsDir, runID+".json"))
	}
}
